            headers = [cell.text_content().strip() for cell in header_cells]
            rows = rows[1:]

        data = []
        for row in rows:
            cells = row.xpath('.//td')
            if cells:
                data.append([cell.text_content().strip() for cell in cells])

        if not data:
            return 0

        df = pd.DataFrame(data, columns=headers if headers else None)

